import {TRANSLATION_LANGUAGES} from './translation-config.js';
export async function openNativeTranslation(profile){
 if(!profile||document.getElementById('nativeTranslation'))return;
 const api=window.zlDesktop,d=document.createElement('dialog');d.id='nativeTranslation';d.className='small-dialog';d.style.cssText='width:440px;max-height:calc(100dvh - 70px);overflow:auto';
 d.innerHTML='<div class="small-dialog-head"><h2>当前账号 · 翻译配置</h2><button type="button" class="nt-close icon-button">×</button></div><p>发送：首次发送先翻译并填回输入框，再次发送才发出。接收：为收到和发出的文字消息提供点击翻译；开启翻译预览后自动显示译文。</p><form><label>翻译服务<select name="provider"><option value="google">Google（免费，无需 Key）</option><option value="deepl">DeepL API Free</option><option value="openai">OpenAI</option><option value="gemini">Gemini</option></select></label><label class="nt-key">API Key（留空保留已保存密钥）<input name="apiKey" type="password" autocomplete="off"></label><p>密钥在本机加密保存。Google 免费通道无需 Key，属于非官方网页接口，可能限流或失效。DeepL 免费 API 仍需申请免费 Key；开启翻译会将相应消息文本发送给所选服务。</p><label class="nt-model">模型名称<input name="model" placeholder="填写此密钥可使用的模型名称"></label><label><input name="sendEnabled" type="checkbox" style="width:auto">开启发送翻译</label><select name="sendLanguage"></select><label><input name="receiveEnabled" type="checkbox" style="width:auto">开启接收翻译</label><select name="receiveLanguage"></select><label><input name="previewEnabled" type="checkbox" style="width:auto">翻译预览（自动翻译消息）</label><p>使用上方接收目标语言翻译收到和发出的消息；未开启预览时，点击消息下方“点击翻译”手动翻译。</p><p class="nt-feedback" role="status"></p><div class="dialog-buttons"><button class="button quiet nt-test" type="button">保存并检测服务</button><button class="button blue" type="submit">保存 / 应用</button></div></form>';
 const f=d.querySelector('form'),q=name=>f.elements.namedItem(name),feedback=d.querySelector('.nt-feedback');for(const dir of ['send','receive'])for(const [id,label] of TRANSLATION_LANGUAGES){const o=document.createElement('option');o.value=id;o.textContent=label;q(dir+'Language').append(o)}
 function fields(){q('previewEnabled').disabled=!q('receiveEnabled').checked;q('receiveLanguage').disabled=!q('receiveEnabled').checked;q('sendLanguage').disabled=!q('sendEnabled').checked;d.querySelector('.nt-key').hidden=q('provider').value==='google';d.querySelector('.nt-model').hidden=!['openai','gemini'].includes(q('provider').value)}q('receiveEnabled').onchange=fields;q('sendEnabled').onchange=fields;q('provider').onchange=()=>{q('apiKey').value='';fields()};
 async function save(test=false){const config={};for(const name of ['provider','model','sendLanguage','receiveLanguage'])config[name]=q(name).value;for(const name of ['sendEnabled','receiveEnabled','previewEnabled'])config[name]=q(name).checked;const buttons=[...d.querySelectorAll('.dialog-buttons button')];buttons.forEach(b=>b.disabled=true);try{await api.translationSave({accountId:profile.id,config,apiKey:q('apiKey').value});q('apiKey').value='';feedback.textContent=test?'正在请求翻译服务…':'已保存并应用到当前账号';if(test){const text=await api.translationTest(profile.id);feedback.textContent='服务返回：'+text}}catch(e){feedback.textContent=e.message}finally{buttons.forEach(b=>b.disabled=false)}}
 f.onsubmit=e=>{e.preventDefault();save()};d.querySelector('.nt-test').onclick=()=>save(true);d.querySelector('.nt-close').onclick=()=>d.close();d.onclose=()=>d.remove();document.body.append(d);d.showModal();
 try{const config=await api.translationGet(profile.id);for(const name of ['provider','model','sendLanguage','receiveLanguage'])q(name).value=config[name];for(const name of ['sendEnabled','receiveEnabled','previewEnabled'])q(name).checked=config[name];feedback.textContent=config.provider==='google'?'Google 免费通道无需 API Key':config.hasKey?'该服务已保存密钥':'请先配置所选服务的 API Key';fields()}catch(e){feedback.textContent=e.message}
}
